import React, { useState, useEffect, useRef } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { useAudio } from '../contexts/AudioContext';
import '../styles/pages/LandingPage.css';

const LandingPage: React.FC = () => {
  const { isPlaying, playLandingMusic } = useAudio();
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const audioRef = useRef<HTMLAudioElement>(null);
  const location = useLocation();
  const navigate = useNavigate();
  const hasTriedPlayRef = useRef(false);
  
  // Asegurar que siempre estemos en la URL con autoplay=true
  useEffect(() => {
    const searchParams = new URLSearchParams(location.search);
    const shouldAutoplay = searchParams.get('autoplay') === 'true';
    
    if (!shouldAutoplay) {
      // Si estamos en la raíz pero sin autoplay, redirigir añadiendo el parámetro
      if (location.pathname === '/') {
        navigate('/?autoplay=true', { replace: true });
      }
    }
  }, [location, navigate]);
  
  // Intentar reproducir música automáticamente al cargar
  useEffect(() => {
    if (!hasTriedPlayRef.current) {
      hasTriedPlayRef.current = true;
      
      const attemptPlay = async () => {
        try {
          console.log("Intento inicial de reproducción automática...");
          await playLandingMusic();
        } catch (error) {
          console.error("Error en reproducción automática:", error);
          
          // Intentar con el elemento HTML como fallback
          if (audioRef.current) {
            try {
              audioRef.current.volume = 0;
              await audioRef.current.play();
              
              // Fade in del volumen
              const fadeIn = () => {
                if (audioRef.current) {
                  audioRef.current.volume = Math.min(audioRef.current.volume + 0.05, 0.5);
                  if (audioRef.current.volume < 0.5) {
                    setTimeout(fadeIn, 100);
                  }
                }
              };
              setTimeout(fadeIn, 300);
            } catch (htmlErr) {
              console.error("También falló reproducción con HTML audio:", htmlErr);
            }
          }
        }
      };
      
      attemptPlay();
      
      // Múltiples intentos con retraso - útil para navegadores estrictos
      const timers: number[] = [];
      [500, 1500, 3000, 5000].forEach(delay => {
        const timer = window.setTimeout(() => {
          if (!isPlaying) {
            console.log(`Intento de reproducción tras ${delay}ms`);
            playLandingMusic().catch(e => console.log(`Error en intento ${delay}ms:`, e));
          }
        }, delay);
        timers.push(timer);
      });
      
      return () => {
        timers.forEach(t => window.clearTimeout(t));
      };
    }
  }, [playLandingMusic, isPlaying]);

  // Verificar existencia de archivos de audio
  useEffect(() => {
    const checkAudioFiles = async () => {
      try {
        const landingResponse = await fetch('/assets/audio/landing-theme.mp3');
        if (!landingResponse.ok) {
          setErrorMessage(`No se encontró el archivo de audio. Estado: ${landingResponse.status}`);
        }
      } catch (error) {
        setErrorMessage("Error al verificar archivos de audio: " + (error instanceof Error ? error.message : "Error desconocido"));
      }
    };
    
    checkAudioFiles();
  }, []);

  return (
    <div className="landing-page">
      {errorMessage && (
        <div className="error-message">
          {errorMessage}
        </div>
      )}
      
      <div className="landing-content">
        <div className="title-container">
          <h1 className="game-title">Heroes&Hostias</h1>
        </div>
        
        <div className="buttons-container">
          <Link to="/login?autoplay=true" className="landing-button login-button">
            <span className="button-text">Iniciar Sesión</span>
          </Link>
          
          <Link to="/register?autoplay=true" className="landing-button register-button">
            <span className="button-text">Registrarse</span>
          </Link>
        </div>
      </div>
      
      <div className="version-footer">
        <span>v1.0.0 Beta</span>
      </div>
      
      {/* Elemento de audio para reproducción directa como fallback */}
      <audio 
        ref={audioRef}
        src="/assets/audio/landing-theme.mp3" 
        loop
        preload="auto"
        style={{ display: 'none' }}
      />
    </div>
  );
};

export default LandingPage;
